/** Retain behavior hooks while attaching their static Tailwind utilities. */
export function pageClasses(className?: string) {
  if (!className) return className;
  const hooks = className.split(/\s+/).filter(Boolean);
  return [...new Set([...hooks, ...hooks.flatMap(hook => sectionUtilities[hook]?.split(" ") ?? [])])].join(" ");
}
